<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import type {BrowseContext} from '../types/model-browse';
import {trainingReaderApi,type TrainingReport,type EvaluationPage} from '../api/training-reader';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import ReportCharts from '../components/ReportCharts.vue';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
const props=defineProps<{context:BrowseContext}>(),api=trainingReaderApi(props.context),reads=useReadScope(props.context),selection=props.context.memory.report,report=ref<TrainingReport|null>(null);
const stateLabels:Record<string,string>={AVAILABLE:'已有报告摘要',PARTIAL:'仅有已记录训练结果',NOT_GENERATED:'报告尚未生成',NOT_FOUND:'报告或任务记录不存在',ERROR:'报告记录读取异常',DEFERRED:'报告超出摘要读取边界'};
function load(){if(!selection)return;for(const key of ['detail','versions','comparison'])reads.cancel(key);detail.value=null;comparison.value=null;tab.value='summary';report.value=null;return reads.run('report',signal=>api.report(selection,signal),value=>{report.value=value})}
function back(){if(selection?.returnPage==='tasks')props.context.openTasks?.();else props.context.returnToAssets()}
function legacy(){if(selection)props.context.legacyReport?.({...selection,algorithmId:report.value?.algorithm_id||selection.algorithmId,versionId:report.value?.version_id||selection.versionId})}
const tab=ref('summary'),detail=ref<EvaluationPage|null>(null),offset=ref(0),historyOffset=ref(0),issue=ref('fp'),other=ref(''),comparison=ref<Record<string,unknown>|null>(null),comparisonOffset=ref(0),classId=ref(''),failedImages=ref<Record<string,boolean>>({}),versionPage=ref(1),versions=ref<{id:string;version_name?:string}[]>([]),versionTotal=ref(0);
const canonical=computed(()=>selection?{...selection,algorithmId:report.value?.algorithm_id||selection.algorithmId,versionId:report.value?.version_id||selection.versionId}:null);
const tabs=[['summary','报告摘要'],['history','训练过程'],['classes','类别指标'],['curves','PR 阈值曲线'],['confusion','混淆矩阵'],['samples','FP / FN 样本'],['compare','版本对比']];
const facts=(value:unknown):[string,unknown][]=>value&&typeof value==='object'?Object.entries(value).filter(([,v])=>v===null||['string','number','boolean'].includes(typeof v)):[];
const records=(value:unknown):Record<string,unknown>[]=>Array.isArray(value)?value.filter(row=>row&&typeof row==='object'):[];
const classRows=computed(()=>records(detail.value?.evaluation?.per_class));
const sampleRows=computed(()=>records(detail.value?.items));
function openTab(key:string){closePreviews();reads.cancel('detail');reads.cancel('versions');reads.cancel('comparison');tab.value=key;offset.value=0;detail.value=null;comparison.value=null;if(key==='history')void historyPage(0);else if(key==='compare'){versionPage.value=1;void loadVersions()}else if(key!=='summary')void loadDetail()}
function historyPage(pageOffset:number){if(!canonical.value)return;historyOffset.value=pageOffset;return reads.run('detail',signal=>api.report(canonical.value!,signal,pageOffset),value=>{report.value=value})}
function loadDetail(){if(!canonical.value)return;detail.value=null;return reads.run('detail',signal=>api.evaluation(canonical.value!,tab.value,offset.value,signal,{...(tab.value==='samples'?{issue:issue.value}:{}),...(classId.value?{class_id:classId.value}:{})}),value=>{detail.value=value})}
function detailPage(delta:number){closePreviews();offset.value=Math.max(0,offset.value+delta*20);void loadDetail()}
function loadVersions(){if(!canonical.value)return;versions.value=[];return reads.run('versions',signal=>api.versions(canonical.value!,versionPage.value,signal),value=>{versions.value=value.items.filter(row=>row.id!==canonical.value?.versionId);versionTotal.value=value.total})}
function compare(pageOffset=0){comparisonOffset.value=pageOffset;if(!canonical.value||!other.value)return;comparison.value=null;return reads.run('comparison',signal=>api.compare(canonical.value!,other.value,signal,pageOffset),value=>{comparison.value=value})}
type PreviewHandle={root:HTMLElement;dispose():void};
const previews=new Set<PreviewHandle>();
function closePreviews(){const api=window as unknown as {closeModalLayer424?(layer:Element):void};for(const handle of previews){handle.dispose();const layer=handle.root.closest('.v424-modal-layer');if(layer)api.closeModalLayer424?.(layer)}previews.clear()}
onBeforeUnmount(closePreviews);
function preview(row:Record<string,unknown>){const url=frozenUrl(row);if(!url)return;const api=(window as unknown as {MaterialPresentation?:{preview(options:unknown):PreviewHandle}}).MaterialPresentation;if(!api)return;closePreviews();const projectBoxes=(key:string,prefix:string)=>records(row[key]).flatMap(box=>{const xy=box.box;if(!Array.isArray(xy)||xy.length!==4||!xy.every(value=>typeof value==='number'&&Number.isFinite(value)))return [];return [{x1:xy[0],y1:xy[1],x2:xy[2],y2:xy[3],label:prefix+' · '+String(box.label??box.class_id??'未提供')}];});const handle=api.preview({image:{id:row.image_id,url,filename:row.filename||row.image_id,width:row.width,height:row.height,boxes:[...projectBoxes('gt_boxes','GT'),...projectBoxes('pred_boxes','预测')]},annotationStatusLabel:'冻结 GT / 预测证据（只读）',sourceLabel:'冻结评测 '+detail.value?.evaluation_id});handle.root.querySelector('[data-tool="edit"]')?.remove();previews.add(handle)}
function classSamples(id:unknown,kind:string){classId.value=String(id??'');issue.value=kind;openTab('samples')}
function classCurve(id:unknown){classId.value=String(id??'');openTab('curves')}
function frozenUrl(row:Record<string,unknown>){const raw=row.preview_url;if(typeof raw!=='string'||!raw.startsWith('/api/'))return '';const url=new URL(raw,window.location.origin);return url.origin===window.location.origin&&url.pathname.startsWith(`/api/v12/projects/${encodeURIComponent(props.context.projectId)}/algorithms/${encodeURIComponent(canonical.value?.algorithmId||'')}/versions/${encodeURIComponent(canonical.value?.versionId||'')}/evaluation/images/`)&&url.searchParams.get('expected_evaluation_id')===detail.value?.evaluation_id&&url.searchParams.get('expected_image_id')===row.image_id&&url.searchParams.get('expected_sha256')===row.image_content_sha256&&Boolean(detail.value?.evaluation_id)&&Boolean(row.image_content_sha256)&&Boolean(row.image_id)?raw:''}
onMounted(()=>void load());
</script>
<template><section class="catalog-preview" aria-label="训练报告与模型质量"><PageHeader title="训练报告与模型质量" eyebrow="训练管理 / 报告阅读" description="只展示已有训练与评测证据，Val 和独立 Test 分开。" badge="只读报告" @back="back"/>
<div class="browse-context"><div><strong>{{ selection?.jobId||'尚未选择任务或版本' }}</strong><small>项目 {{ context.projectId }} · 算法 {{ report?.algorithm_id||selection?.algorithmId||'未提供' }} · 版本 {{ report?.version_id||selection?.versionId||'未提供' }}</small></div><div class="preview-actions"><el-button @click="back">返回来源列表</el-button><el-button :disabled="!selection||reads.busy.report" @click="load">重新读取报告</el-button></div></div>
<el-alert v-if="reads.errors.report" :title="reads.errors.report" type="error" :closable="false"/><el-skeleton v-if="reads.busy.report" :rows="10" animated/>
<template v-else-if="report"><div class="report-state"><el-tag type="info" effect="plain">{{ stateLabels[report.state]||report.state }}</el-tag><span>{{ report.source||'来源未提供' }}</span><p v-if="report.message">{{ report.message }}</p></div>
<nav class="report-tabs" aria-label="报告内容"><el-button v-for="[key,label] in tabs" :key="key" :type="tab===key?'primary':'default'" :disabled="key!=='summary'&&key!=='history'&&!canonical?.versionId" @click="openTab(key)">{{ label }}</el-button></nav>
<template v-if="tab==='summary'">
<div v-if="report.val_metrics||report.test_metrics" class="report-metrics"><section class="browse-panel"><header><h2>Val 指标</h2></header><ReadOnlyFacts :fields="Object.entries(report.val_metrics||{})"/></section><section class="browse-panel"><header><h2>独立 Test 指标</h2></header><ReadOnlyFacts :fields="[['评测状态',report.test_status],...Object.entries(report.test_metrics||{})]"/></section></div>
<section v-if="report.configuration||report.result" class="browse-panel report-section"><h2>配置与执行结果</h2><ReadOnlyFacts :fields="Object.entries(report.configuration||{})"/><ReadOnlyFacts :fields="Object.entries(report.result||{})"/></section>
<section v-if="report.credibility||report.warnings?.length" class="browse-panel report-section"><h2>质量与预警</h2><ReadOnlyFacts :fields="Object.entries(report.credibility||{})"/><ul v-if="report.warnings?.length"><li v-for="(warning,index) in report.warnings" :key="index">{{ warning }}</li></ul><p v-else class="evidence-note">没有提供预警证据，不能据此认定质量验收通过。</p></section>

</template>
<div v-if="reads.errors.detail||reads.errors.versions||reads.errors.comparison" role="alert" class="evidence-note">{{ reads.errors.detail||reads.errors.versions||reads.errors.comparison }}<el-button @click="openTab(tab)">重试读取</el-button></div>
<el-skeleton v-if="reads.busy.detail||reads.busy.versions||reads.busy.comparison" :rows="5" animated/>
<section v-if="tab==='history'" class="browse-panel report-section" aria-label="训练过程分页"><h2>已记录训练过程</h2><ReportCharts :history="report.history||[]"/><el-table :data="report.history||[]" max-height="480" class="grouped-report-table"><el-table-column label="Epoch" width="70"><template #default="{row}">{{ row.epoch??'未提供' }}</template></el-table-column><el-table-column label="质量指标" min-width="160"><template #default="{row}"><ReadOnlyFacts :fields="['map50','map50_95','precision','recall','f1'].map(key=>[key,row[key]] as [string,unknown])"/></template></el-table-column><el-table-column label="Train / Val 损失" min-width="165"><template #default="{row}"><ReadOnlyFacts :fields="['box_loss','val_box_loss','cls_loss','val_cls_loss'].map(key=>[key,row[key]] as [string,unknown])"/></template></el-table-column><el-table-column label="学习率 / 耗时" min-width="155"><template #default="{row}"><ReadOnlyFacts :fields="[['learning_rate',row.learning_rate],['duration_seconds',row.duration_seconds]]"/></template></el-table-column></el-table><div class="preview-actions"><el-button :disabled="historyOffset===0||reads.busy.detail" @click="historyPage(Math.max(0,historyOffset-100))">上一页训练过程</el-button><span>偏移 {{ report.history_offset??historyOffset }} · 总数 {{ report.history_total??'未提供' }}</span><el-button :disabled="!report.history_has_next||reads.busy.detail" @click="historyPage(historyOffset+100)">下一页训练过程</el-button></div></section>
<section v-if="detail&& !reads.busy.detail" class="browse-panel report-section" aria-label="独立Test详细报告"><h2>{{ tabs.find(row=>row[0]===tab)?.[1] }}</h2><div v-if="classId" class="preview-actions"><span>类别筛选 {{ classId }}</span><el-button @click="classId='';offset=0;loadDetail()">清除类别筛选</el-button></div><p>状态 {{ detail.state||'未提供' }} · 冻结评测 {{ detail.evaluation_id||'未提供' }}</p><p v-if="detail.message">{{ detail.message }}</p><ReadOnlyFacts :fields="facts(detail.evaluation)"/>
<template v-if="tab==='classes'"><el-table :data="classRows" class="grouped-report-table" empty-text="没有已记录类别指标"><el-table-column label="类别" min-width="95"><template #default="{row}"><ReadOnlyFacts :fields="[['class_id',row.class_id],['label',row.label]]"/></template></el-table-column><el-table-column label="P / R / mAP / F1" min-width="160"><template #default="{row}"><ReadOnlyFacts :fields="['precision','recall','f1','map50','map50_95'].map(key=>[key,row[key]] as [string,unknown])"/></template></el-table-column><el-table-column label="GT / 预测 / TP" min-width="145"><template #default="{row}"><ReadOnlyFacts :fields="[['GT',row.ground_truth_count],['预测',row.prediction_count],['TP',row.true_positive]]"/></template></el-table-column><el-table-column label="FP / FN 诊断" min-width="150"><template #default="{row}"><div class="class-diagnostics"><el-button link @click="classSamples(row.class_id,'fp')">FP {{ row.false_positive??'未提供' }}</el-button><el-button link @click="classSamples(row.class_id,'fn')">FN {{ row.false_negative??'未提供' }}</el-button><el-button link @click="classCurve(row.class_id)">查看类别曲线</el-button></div></template></el-table-column></el-table></template>
<template v-if="tab==='curves'||tab==='confusion'"><ReportCharts :evaluation="detail.evaluation||{}"/><p class="evidence-note">PR 为已记录置信度阈值采样，不等同 AP 积分曲线。混淆矩阵及统计遵循该冻结评测协议。</p><details><summary>查看原协议字段</summary><ReadOnlyFacts :fields="facts(detail.evaluation?.confidence_curve_protocol||detail.evaluation?.confusion_matrix)"/></details></template>
<template v-if="tab==='samples'"><div class="preview-actions"><label>错误类型<select v-model="issue" aria-label="样本错误类型" @change="offset=0;loadDetail()"><option value="tp">TP 正确识别</option><option value="fp">FP 误检</option><option value="fn">FN 漏检</option></select></label></div><div class="frozen-samples"><article v-for="(row,index) in sampleRows" :key="String(row.image_id||index)"><h3>{{ row.filename||row.image_id||'冻结样本' }}</h3><img v-if="frozenUrl(row)&&!failedImages[String(row.image_id)]" :src="frozenUrl(row)" @error="failedImages[String(row.image_id)]=true" :alt="String(row.filename||row.image_id||'冻结评测图片')" loading="lazy"><p v-else>冻结图片未提供或读取失败<el-button v-if="frozenUrl(row)" @click="failedImages[String(row.image_id)]=false">重试冻结图片</el-button></p><el-button :disabled="!frozenUrl(row)" @click="preview(row)">放大 GT / 预测叠加对照</el-button><ReadOnlyFacts :fields="facts(row)"/><p>GT 框 {{ records(row.gt_boxes).length }} · 预测框 {{ records(row.pred_boxes).length }}</p><p v-if="row.boxes_truncated||row.gt_boxes_truncated||row.pred_boxes_truncated">框证据已截断，不能据此覆盖正式标注。</p><details><summary>查看冻结 GT / 预测框</summary><pre>{{ {gt:row.gt_boxes,predictions:row.pred_boxes} }}</pre></details></article></div><p v-if="!sampleRows.length">当前条件下没有已记录样本；不推断整体错误为零。</p></template>
<div class="preview-actions"><el-button :disabled="offset===0||reads.busy.detail" @click="detailPage(-1)">上一页报告明细</el-button><span>偏移 {{ detail.offset??offset }} · 总数 {{ detail.total??'未提供' }}</span><el-button :disabled="!(detail.has_next??((detail.total??0)>offset+20))||reads.busy.detail" @click="detailPage(1)">下一页报告明细</el-button></div></section>
<section v-if="tab==='compare'" class="browse-panel report-section" aria-label="版本可比性"><h2>版本对比</h2><div class="preview-actions"><select v-model="other" aria-label="对照版本"><option value="">请选择已保存版本</option><option v-for="row in versions" :key="row.id" :value="row.id">{{ row.version_name||row.id }}</option></select><el-button :disabled="!other||reads.busy.comparison" @click="compare(0)">读取版本对比</el-button><el-button :disabled="versionPage===1||reads.busy.versions" @click="versionPage--;loadVersions()">上一页版本</el-button><el-button :disabled="versionPage*20>=versionTotal||reads.busy.versions" @click="versionPage++;loadVersions()">下一页版本</el-button></div><template v-if="comparison"><p role="status">{{ comparison.comparable===true?'原评测合同确认可比':comparison.comparable===false?'原评测合同判定不可比':'可比性尚未确认' }}</p><ReadOnlyFacts :fields="facts(comparison)"/><p v-if="comparison.reason_codes">{{ comparison.reason_codes }}</p><template v-if="comparison.comparable===true"><h3>指标变化（原响应）</h3><pre>{{ comparison.metrics }}</pre><h3>参数差异</h3><pre>{{ comparison.parameter_differences }}</pre><h3>逐类对比</h3><el-table :data="records(comparison.classes)"><el-table-column v-for="key in ['class_id','label','before','after','metrics','regressed']" :key="key" :prop="key" :label="key" min-width="110"><template #default="{row}"><span v-if="row[key]===null||row[key]===undefined">未提供</span><pre v-else>{{ row[key] }}</pre></template></el-table-column></el-table></template><p v-else>未确认可比时不展示版本优劣结论。</p><div class="preview-actions"><el-button :disabled="comparisonOffset===0||reads.busy.comparison" @click="compare(Math.max(0,comparisonOffset-20))">上一页对比</el-button><span>偏移 {{ comparison.offset??comparisonOffset }} · 类别总数 {{ comparison.total??'未提供' }}</span><el-button :disabled="!comparison.has_next||reads.busy.comparison" @click="compare(comparisonOffset+20)">下一页对比</el-button></div></template></section>
</template><el-empty v-else-if="!selection" description="请从训练任务或算法版本选择报告"/>
<div v-if="selection" class="management-actions"><el-button @click="legacy">原完整报告：PR 曲线 / 混淆矩阵 / 错误样本</el-button></div></section></template>

<style scoped>.grouped-report-table :deep(.readonly-facts){display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.7fr);gap:5px 7px;margin:0;font-size:12px}.grouped-report-table :deep(.readonly-facts dt),.grouped-report-table :deep(.readonly-facts dd){overflow-wrap:anywhere;margin:0;white-space:normal}.class-diagnostics{display:flex;flex-direction:column;align-items:flex-start;gap:6px}.class-diagnostics :deep(.el-button){margin:0}.report-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.report-tabs :deep(.el-button){margin-left:0}.report-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.report-section{margin:16px 0;min-width:0;overflow:auto}.frozen-samples{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.frozen-samples img{display:block;max-width:100%;height:auto;max-height:300px;object-fit:contain}.frozen-samples article{min-width:0;border:1px solid #ddd;padding:12px;border-radius:8px}.report-section pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.report-section select{min-height:32px;max-width:100%}@media(max-width:768px){.report-metrics{grid-template-columns:1fr}}</style>
